local JQRichTextConstants = require("src/ui/components/reach/richtext/JQRichTextConstants")
local JQRichTextUtils = class("JQRichTextUtils")

function JQRichTextUtils:ctor()
    self:initData()
end

function JQRichTextUtils:initData()
    self.uuid = 0
    self.richTextIdSeeds = {}
    self.groupIndexSeed = 0
end

function JQRichTextUtils:nextUUID()
    self.uuid = self.uuid + 1
    return self.uuid
end

function JQRichTextUtils:clearRichTextIdSeed(key)
    if not key then
        self.richTextIdSeeds = {}
    else
        self.richTextIdSeeds[key] = 0
    end
end

function JQRichTextUtils:updateRichTextIdSeed(id)
    local key, idSeed = id, 0
    local startPos, endPos = string.find(id, "_[0-9]+$")
    if startPos then
        key = string.sub(id, 1, startPos - 1)
        idSeed = checkint(string.sub(id, startPos + 1))
    end
    self.richTextIdSeeds[key] = self.richTextIdSeeds[key] or 0
    if idSeed > self.richTextIdSeeds[key] then
        self.richTextIdSeeds[key] = idSeed
    end
end

function JQRichTextUtils:nextRichTextId(key)
    self.richTextIdSeeds[key] = self.richTextIdSeeds[key] or 0
    self.richTextIdSeeds[key] = self.richTextIdSeeds[key] + 1
    return key .. "_" .. self.richTextIdSeeds[key]
end

function JQRichTextUtils:updateGroupIndexSeed(groupIndexSeed)
    if self.groupIndexSeed < groupIndexSeed then
        self.groupIndexSeed = groupIndexSeed
    end
end

function JQRichTextUtils:newGroupIndex()
    self.groupIndexSeed = self.groupIndexSeed + 1
    return self.groupIndexSeed
end

function JQRichTextUtils:isAlignEqual(this, other)
    return this.groupAlign == other.groupAlign
end

function JQRichTextUtils:isFormatSimilar(this, other)
    if this.groupIndex ~= other.groupIndex or this.type ~= other.type then
        return false
    end

    if this.type == JQRichTextConstants.TYPES.IMAGE then
        return self:isImageSimilar(this, other)
    else
        return self:isTextSimilar(this, other)
    end
end

function JQRichTextUtils:isTextSimilar(this, other)
    local isBgColorEqual = false
    if this.hasBgColor and other.hasBgColor then
        isBgColorEqual = self:isColorEqual(this.bgColor, other.bgColor)
    else
        isBgColorEqual = not this.hasBgColor and not other.hasBgColor
    end
    return isBgColorEqual and
            self:isColorEqual(this.color, other.color) and
            this.fontName == other.fontName and
            this.fontSize == other.fontSize and
            checkbool(this.bold) == checkbool(other.bold) and
            this.underlineWidth == other.underlineWidth
end

function JQRichTextUtils:isImageSimilar(this, other)
    return self:isSizeEqual(this.imgSize, other.imgSize)
end

function JQRichTextUtils:isHexColor(color)
    return type(color) == "string"
end

function JQRichTextUtils:toHexColor(color)
    local ret = {'#'}
    local rgb = {color.r, color.g, color.b}
    table.foreach(rgb, function(_, c)
        table.insert(ret, string.format('%02x', c))
    end)
    return table.concat(ret)
end

function JQRichTextUtils:toColor(hexColor)
    local r, g, b
    local n = tonumber("0x" .. string.sub(hexColor, 2))
    b, n = n % 256, math.floor(n / 256)
    g, n = n % 256, math.floor(n / 256)
    r, n = n % 256, math.floor(n / 256)
    return {r = r, g = g, b = b}
end

function JQRichTextUtils:isColorEqual(c1, c2)
    if c1 and c2 then
        return c1.r == c2.r and c1.g == c2.g and c1.b == c2.b
    elseif not c1 and not c2 then
        return true
    else
        return false
    end
end

function JQRichTextUtils:isSizeEqual(s1, s2)
    if s1 and s2 then
        return s1.width == s2.width and s1.height == s2.height
    elseif not s1 and not s2 then
        return true
    else
        return false
    end
end

function JQRichTextUtils:isAlnum(char)
    char = string.lower(char)
    return (char >= "a" and char <= "z") or (char >= "0" and char <= "9")
end

function JQRichTextUtils:mergeFormat(dst, src)
    if dst.tailWithLF then
        dst.text = dst.text .. "\n"
    end
    dst.text = dst.text .. src.text
    dst.tailWithLF = src.tailWithLF
end

--[[
    <d><t></t></d>
    <d><t><b></b></t></d>
    <d><t><op></op></t></d>
    <d><t><b><op></op></b></t></d>
]]--
function JQRichTextUtils:isNullHtmlText(htmlText)
    if not htmlText then
        return true
    end

    local listBegin = {"<t[^>]*>", "<b[^>]*>", "<op[^>]*>"}
    local listEnded = {"</t>", "</b>", "</op>"}
    local middle = "([^<]+)"

    local isNull = true
    for i = 1, #listBegin do
        local pattern = listBegin[i] .. middle .. listEnded[i]
        local s = string.match(htmlText, pattern)

        if s then
            isNull = false
            break
        end
    end

    return isNull
end

function JQRichTextUtils:selectRenderedIndex(indices, callback)
    local beganNodeIndex, beganLetterIndex, beganInFront = indices.beganNodeIndex, indices.beganLetterIndex, indices.beganInFront
    local endedNodeIndex, endedLetterIndex, endedInFront = indices.endedNodeIndex, indices.endedLetterIndex, indices.endedInFront

    if beganNodeIndex > endedNodeIndex then
        beganNodeIndex, endedNodeIndex = endedNodeIndex, beganNodeIndex
        beganLetterIndex, endedLetterIndex = endedLetterIndex, beganLetterIndex
        beganInFront, endedInFront = endedInFront, beganInFront
    elseif beganNodeIndex == endedNodeIndex then
        if beganLetterIndex > endedLetterIndex or (beganLetterIndex == endedLetterIndex and not beganInFront) then
            beganLetterIndex, endedLetterIndex = endedLetterIndex, beganLetterIndex
            beganInFront, endedInFront = endedInFront, beganInFront
        end
    end

    if beganNodeIndex == endedNodeIndex then
        if not (beganLetterIndex == endedLetterIndex and beganInFront == endedInFront) then
            callback({nodeIndex = beganNodeIndex,
                      beganIndex = beganLetterIndex, beganInFront = beganInFront,
                      endedIndex = endedLetterIndex, endedInFront = endedInFront},
                    true, true)
        end
    else
        callback({nodeIndex = beganNodeIndex,
                  beganIndex = beganLetterIndex, beganInFront = beganInFront,
                  endedIndex = -1, endedInFront = false},
                true, false)
        for index = beganNodeIndex + 1, endedNodeIndex - 1 do
            callback({nodeIndex = index,
                      beganIndex = 1, beganInFront = true,
                      endedIndex = -1, endedInFront = false},
                    false, false)
        end
        callback({nodeIndex = endedNodeIndex,
                  beganIndex = 1, beganInFront = true,
                  endedIndex = endedLetterIndex, endedInFront = endedInFront},
                false, true)
    end
end

local richTextUtils = JQRichTextUtils.new()
return richTextUtils